const prev = $('Build Prompt (POLICY)').first().json;
const res = $input.first().json;
const text = (res.content || []).map(c => c.text || '').join('');
let out;
try {
  const m = text.match(/\{[\s\S]*\}/);
  out = JSON.parse(m ? m[0] : text);
} catch (e) {
  out = {
    category: 'other', language: 'en', order_name: '', confidence: 0,
    needs_human: true, proposed_action: 'none', action_details: '',
    summary_nl: 'AI-antwoord kon niet gelezen worden, handmatig oppakken.',
    reply_html: ''
  };
}
return [{ json: { store: prev.store, email: prev.email, orders: prev.orders, ai: out } }];
